import {HuntGame,ARENA,BONUS,distance} from './engine.js';
import {HuntWorld} from './world.js';
import {cats,findCat} from './cats.js';
import {VirtualStick,movementVector,cameraDelta} from './controllers.js';
const $=s=>document.querySelector(s),canvas=$('#game'),mapCanvas=$('#map'),map=mapCanvas.getContext('2d'),game=new HuntGame(),keys=new Set();
let world,last=0,worldTime=0,lastMode='',inspectPrevious='intro',helpPrevious=null,spin=false,drag=null,toastTimer,popupTimer,speechTimer,audio,muted=false,best=0,mapTimer=0,stepTimer=0;
try{muted=(localStorage.getItem('mouse-hunt-sound')||localStorage.getItem('errand-sound'))==='off';best=Number(localStorage.getItem('mouse-hunt-best')||0);}catch{}
const moving=()=>game.mode==='playing'&&world&&!world.inspect,leftStick=new VirtualStick($('#move-stick'),moving),rightStick=new VirtualStick($('#look-stick'),moving);
function resetInput(){keys.clear();leftStick.reset();rightStick.reset();drag=null;}
function text(s,v){const e=$(s);if(e.textContent!==String(v))e.textContent=v;}
function html(s,v){const e=$(s);if(e.innerHTML!==v)e.innerHTML=v;}
function toast(v){text('#toast',v);$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function popup(v){const e=$('#score-popup');e.textContent=v;e.classList.remove('show');void e.offsetWidth;e.classList.add('show');clearTimeout(popupTimer);popupTimer=setTimeout(()=>e.classList.remove('show'),1500);}
function say(v){text('#cat-speech',v);$('#cat-speech').classList.add('show');clearTimeout(speechTimer);speechTimer=setTimeout(()=>$('#cat-speech').classList.remove('show'),2200);}
function unlock(){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();}catch{}}
function tone(f,t=0,d=.18,end=0,volume=.025){if(!audio||muted)return;const o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime+t;o.type='sine';o.frequency.setValueAtTime(f,now);if(end)o.frequency.exponentialRampToValueAtTime(end,now+d);g.gain.setValueAtTime(.001,now);g.gain.exponentialRampToValueAtTime(volume,now+.014);g.gain.exponentialRampToValueAtTime(.001,now+d);o.connect(g);g.connect(audio.destination);o.start(now);o.stop(now+d+.02);}
function sound(type){unlock();if(type==='jump')tone(220,0,.2,700);else if(type==='meow'){tone(440,0,.23,780);tone(710,.18,.3,320);}else if(type==='step')tone(110,0,.05,80,.006);else if(type==='gameover'){tone(440,0,.25,220);tone(220,.25,.35,110);}else{const notes=type==='clear'||type==='win'?[523,659,784,1046]:type==='bonus'?[784,1046,1568]:type==='catch'?[880,1175]:[523,784];notes.forEach((n,i)=>tone(n,i*.07,.18));}}
function soundLabel(){text('#sound',muted?'♪ 音 OFF':'♪ 音 ON');$('#sound').setAttribute('aria-pressed',String(!muted));}
$('#sound').addEventListener('click',()=>{muted=!muted;soundLabel();sound('bonus');try{localStorage.setItem('mouse-hunt-sound',muted?'off':'on');}catch{}});soundLabel();
try{world=new HuntWorld(canvas);}catch(error){text('#welcome h2','3Dを表示できませんでした');text('#welcome p','WebGL 2対応ブラウザーで開いてください。');console.error(error);}
function selectCat(id,announce=false){game.selectCat(id);const character=game.character,name=character.name;for(const b of document.querySelectorAll('[data-cat]')){const on=b.dataset.cat===game.selectedCat;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));}$('.welcome-cat').className='welcome-cat portrait-'+game.selectedCat;text('#selected-name',name+' · '+character.trait);text('#cat-trait',character.description);text('#cat-quote','「'+character.quote+'」');$('#cat-profile').style.setProperty('--personality-color',character.color);text('#inspect-name',name+'の3Dルーム');try{localStorage.setItem('mouse-hunt-cat',game.selectedCat);}catch{}if(announce){if(game.mode==='playing')toast(name+' · '+character.trait);game.personality('select',true);if(world?.inspect){world.setInspect(true,game.selectedCat);world.previewPersonality(game.selectedCat);}sound('bonus');}}
for(const b of document.querySelectorAll('[data-cat]'))b.addEventListener('click',()=>selectCat(b.dataset.cat,true));let saved='monaka';try{saved=localStorage.getItem('mouse-hunt-cat')||localStorage.getItem('errand-cat')||'monaka';}catch{}selectCat(saved);
function scrollToGame(){$('.play-area').scrollIntoView({block:'start',behavior:'auto'});}
function focusStage(){resetInput();world.inspect=false;world.yaw=0;world.pitch=.97;world.zoom=1;world.overview=false;world.snap=true;text('#camera','◈ 全体');lastMode='';canvas.focus({preventScroll:true});scrollToGame();}
function start(){if(!world)return;game.start();focusStage();sound('bonus');toast('近づくだけで自動キャッチ！ まずは8匹つかまえよう。');}
$('#start').addEventListener('click',start);$('#again').addEventListener('click',start);$('#restart').addEventListener('click',start);$('#next-stage').addEventListener('click',()=>{if(game.nextStage())focusStage();});$('#retry').addEventListener('click',()=>{if(game.retryStage()){focusStage();toast('もう一度！ 目標 '+game.stage.target+'匹をつかまえよう。');}});
function pause(){if(world?.inspect){closeInspect();return;}if(game.mode==='playing'){game.mode='paused';resetInput();}else if(game.mode==='paused'){game.mode='playing';resetInput();canvas.focus({preventScroll:true});scrollToGame();}}
$('#pause').addEventListener('click',pause);$('#resume').addEventListener('click',pause);$('#jump').addEventListener('click',()=>{unlock();game.pounce();});$('#meow').addEventListener('click',()=>{unlock();game.meow();});
$('#camera').addEventListener('click',()=>{if(!world)return;world.overview=!world.overview;world.snap=true;text('#camera',world.overview?'◈ 猫のそば':'◈ 全体');canvas.focus({preventScroll:true});});
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.play-area').requestFullscreen();}catch{toast('そのままの画面でも遊べます。');}});
function openInspect(){if(!world||world.inspect)return;inspectPrevious=game.mode;game.mode='inspect';resetInput();spin=false;world.setInspect(true,game.selectedCat);scrollToGame();}
function closeInspect(){if(!world)return;world.setInspect(false,game.selectedCat);game.mode=inspectPrevious;resetInput();if(game.mode==='playing')canvas.focus({preventScroll:true});}
$('#inspect').addEventListener('click',openInspect);$('#close-inspect').addEventListener('click',closeInspect);for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>{world.previewYaw=b.dataset.view==='front'?0:b.dataset.view==='side'?Math.PI/2:Math.PI;spin=false;});$('#preview-trait').addEventListener('click',()=>{spin=false;world.previewPersonality(game.selectedCat);});$('#spin').addEventListener('click',()=>spin=!spin);
function help(){helpPrevious=game.mode;if(game.mode==='playing')game.mode='paused';resetInput();lastMode='';$('#help-dialog').showModal();}
$('#help-top').addEventListener('click',help);$('#help-game').addEventListener('click',help);$('#help-close').addEventListener('click',()=>$('#help-dialog').close());$('#help-done').addEventListener('click',()=>$('#help-dialog').close());$('#help-dialog').addEventListener('close',()=>{if(helpPrevious!==null)game.mode=helpPrevious;helpPrevious=null;lastMode='';resetInput();});
function bestScore(){if(game.score>best){best=game.score;try{localStorage.setItem('mouse-hunt-best',String(best));}catch{}}}
function panels(){if(lastMode===game.mode)return;lastMode=game.mode;resetInput();$('#cat-speech').hidden=game.mode!=='playing';if(game.mode!=='playing'){clearTimeout(speechTimer);$('#cat-speech').classList.remove('show');}for(const [id,mode] of [['welcome','intro'],['pause-screen','paused'],['stage-screen','stageclear'],['result-screen','won'],['gameover-screen','gameover'],['inspect-tools','inspect'],['dual-controls','playing']])$('#'+id).hidden=game.mode!==mode||(mode==='paused'&&$('#help-dialog').open);$('#scene-hud').hidden=game.mode!=='playing';text('#pause',game.mode==='paused'?'▶':'Ⅱ');$('#pause').setAttribute('aria-label',game.mode==='paused'?'再開':'一時停止');$('#pause').disabled=!['playing','paused','inspect'].includes(game.mode);
 if(['stageclear','gameover','won'].includes(game.mode))bestScore();
 if(game.mode==='stageclear'){text('#stage-clear-title',game.caught+'匹ゲット！ CLEAR!');text('#stage-clear-message','STAGE '+game.level+'「'+game.stage.name+'」');html('#stage-stats','<span>時間ボーナス +'+game.stageBonus+'pt</span><span>合計 '+game.score+'pt</span>');text('#next-stage','STAGE '+(game.level+1)+' へ ▶');text('#next-hint','次は '+(game.stage.target+4)+'匹！ ねずみがもっと速くなるよ。');}
 if(game.mode==='won'){text('#result-message',findCat(game.selectedCat).name+'が合計'+game.totalCaught+'匹をキャッチ！');html('#result-stats','<span>★ '+game.score+'pt</span><span>BEST '+best+'pt</span>');}
 if(game.mode==='gameover')text('#failure-message',game.caught+' / '+game.stage.target+'匹をキャッチ！ 「にゃあ」でゆっくりにしてみよう。');
}
function hud(){const left=Math.max(0,game.stage.target-game.caught),sec=Math.ceil(game.remaining);text('#step-no',String(game.level).padStart(2,'0'));text('#step-label','STAGE '+game.level+' / 5');text('#location-name',game.stage.name);text('#caught-count','🐭 '+game.caught+' / '+game.stage.target);text('#stage-goal','あと'+left+'匹！');$('#points-fill').style.width=Math.min(100,game.caught/game.stage.target*100)+'%';text('#score',game.score+' pt');text('#best-score','BEST '+best);text('#countdown',String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'));$('#countdown').classList.toggle('urgent',sec<20);text('#goal-distance','🐭 あと'+left+'匹でステージクリア');text('#goal-title','近づくだけでキャッチ！');text('#goal-hint',game.remaining<20?'あと少し！ 時計のボーナスで時間を増やせるよ。':'左で移動。とびつくと、遠くまでキャッチ！');$('#jump').disabled=game.pounceCooldown>0||!game.player.grounded;$('#meow').disabled=game.meowCooldown>0;text('#pounce-ready',game.pounceCooldown>0?'あと'+Math.ceil(game.pounceCooldown)+'秒':'とびつく');text('#meow-ready',game.meowCooldown>0?'あと'+Math.ceil(game.meowCooldown)+'秒':'ゆっくりに');$('#combo-chip').hidden=game.combo<2;text('#combo-chip','COMBO ×'+game.combo+'　'+Math.ceil(game.comboTimer)+'秒');const buffs=[];if(game.boost>0)buffs.push('⚡ 猫スピード '+Math.ceil(game.boost)+'秒');if(game.slow>0)buffs.push('❄ ねずみスロー '+Math.ceil(game.slow)+'秒');if(game.double>0)buffs.push('×2 得点2倍 '+Math.ceil(game.double)+'秒');html('#buffs',buffs.map(s=>'<span>'+s+'</span>').join(''));text('#speed-note','ねずみ速度 ×'+(game.stage.speed/1.7).toFixed(1));text('#status',game.mode==='inspect'?'前・横・後ろも、立体で見られるよ。':game.mode==='intro'?'猫を動かして、ねずみに近づくだけ！':game.combo>1?'連続キャッチ！ 次も7秒以内でコンボをつなごう！':'近づくだけで自動キャッチ！ SPACEでとびつく、Fでにゃあ。');}
function drawMap(){const x=v=>8+(v+12)/24*152,z=v=>10+(v+12)/24*172;map.fillStyle='#fff8e4';map.fillRect(0,0,168,192);map.fillStyle='#b5d19a';map.fillRect(6,8,156,176);map.fillStyle='#bd9e73';for(const q of ARENA.obstacles)map.fillRect(x(q.x),z(q.z),q.w/24*152,q.d/24*172);for(const m of game.mice)if(m.active){map.fillStyle=m.gold?'#c6952f':'#647589';map.beginPath();map.arc(x(m.x),z(m.z),m.gold?3:2.4,0,7);map.fill();}for(const b of game.bonuses)if(b.active){map.fillStyle='#f7e19d';map.strokeStyle='#b69b50';map.fillRect(x(b.x)-2.8,z(b.z)-2.8,5.6,5.6);map.strokeRect(x(b.x)-2.8,z(b.z)-2.8,5.6,5.6);}map.fillStyle='#dc7c62';map.beginPath();map.arc(x(game.player.x),z(game.player.z),4,0,7);map.fill();map.strokeStyle='#fff5d4';map.lineWidth=1.7;map.stroke();}
function frame(ts){requestAnimationFrame(frame);if(world?.compact&&ts-last<32)return;const dt=Math.min((ts-last)/1000||0,.18);last=ts;worldTime+=dt;if(world&&game.mode==='playing'){const x=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),y=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);let remaining=dt;while(remaining>0&&game.mode==='playing'){const step=Math.min(.04,remaining),delta=cameraDelta(rightStick,step);world.rotate(delta.yaw,delta.pitch);game.update(step,movementVector(x,y,leftStick,world.yaw));remaining-=step;}}
 for(const e of game.events.splice(0)){if(e.type==='personality'){if(game.mode==='playing')say(e.text);continue;}if(e.type==='points')popup(e.text);else if(!['clear','win','gameover','jump'].includes(e.type))toast(e.text);if(e.type==='meow')world?.meowEffect(game.player.x,game.player.z);if(e.type==='catch')world?.burst(game.player.x,game.player.z,e.points>=50);if(e.type!=='points')sound(e.type);}
 panels();hud();mapTimer-=dt;if(mapTimer<=0){drawMap();mapTimer=.12;}if(game.mode==='playing'&&game.player.moving&&game.player.grounded){stepTimer-=dt;if(stepTimer<=0){sound('step');stepTimer=.29;}}if(world){if(world.inspect&&spin)world.previewYaw+=dt*.7;world.draw(game,worldTime,dt);}}
document.addEventListener('keydown',e=>{if($('#help-dialog').open)return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(!['w','a','s','d','ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','f','v','Escape'].includes(k))return;if(k===' '&&game.mode==='intro')return;e.preventDefault();if(!e.repeat){if(k==='Escape'){pause();return;}if(k===' ')game.pounce();if(k==='f')game.meow();if(k==='v'&&game.mode==='playing')$('#camera').click();}keys.add(k);});document.addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));
function suspend(){resetInput();if(game.mode==='playing')game.mode='paused';}window.addEventListener('blur',suspend);document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();});window.addEventListener('resize',()=>{resetInput();if(game.mode==='playing')requestAnimationFrame(scrollToGame);});
canvas.addEventListener('pointerdown',e=>{if(!world||!['playing','inspect'].includes(game.mode))return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY};});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;world.rotate((e.clientX-drag.x)*.012,(e.clientY-drag.y)*.004);drag.x=e.clientX;drag.y=e.clientY;spin=false;});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>drag=null);canvas.addEventListener('wheel',e=>{if(!world||!e.altKey)return;e.preventDefault();world.zoom=Math.max(.7,Math.min(1.4,world.zoom+e.deltaY*.001));},{passive:false});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();suspend();toast('3D表示が中断されました。ページを再読み込みしてください。');});
if(world){$('#start').disabled=false;text('#start','ねずみを追いかける ▶');}panels();hud();drawMap();requestAnimationFrame(frame);
